	{ title = "Stormwind", note = "Train, then leave by the main gate and follow the road east through Elwynn Forest.\nLook to the Stars in Darkshire needs a Bronze Tube. Its vendors keep only one or two, and Herble Baubbletump in Darkshire is nearly always sold out: buy one at the Auction House in the Trade District on your way out. An engineer can make one too.", goals = {
		{ t = "train", class = true, only = { classes = {"WARRIOR", "PALADIN", "HUNTER", "ROGUE", "PRIEST", "MAGE", "WARLOCK", "DRUID"} }, note = "Level 18 and 20 spells" },
